pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Create a simple token contract for the target
        address token = address(new SimpleToken());
        // Give this contract some tokens to transferFrom
        SimpleToken(token).mint(address(this), 100);

        // Approve the C contract to transfer from this contract
        SimpleToken(token).approve(address(c), 100);

        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vs = new uint[](1);
        vs[0] = 50;

        // Call transfer - it should succeed in reference version
        bool success;
        try c.transfer(token, tos, vs) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        require(balanceOf[from] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

